import {useMutation, useSuspenseQuery} from "@tanstack/react-query";

import {EntryList} from "./-local/entry-list";
import {fetchEntries, postEntry} from "./entry-api";

export const EntriesPage = () => {
  const response = useSuspenseQuery({
    queryKey: ["entries"],
    queryFn: fetchEntries,
    select: (data) => ({
      items: data.entries.map((entry) => ({id: entry.id, label: entry.title.trim()})),
      meta: {total: data.total},
    }),
  });
  const mutation = useMutation({mutationFn: postEntry});

  return <EntryList items={response.data.items} total={response.data.meta.total} onCreate={mutation.mutate} />;
};
